function alts(label: string, project: string): FictionGuideDefinition["alts"] {
  return {
    hero: `${label} yazarlığı için İlkOku ekranı, çalışma kartları ve türe özgü materyallerle hazırlanmış sıcak editoryal çalışma masası`,
    ideaFlow: `${label} fikrinin çekirdek sorudan çatışmaya dönüşümünü gösteren eğitim akışı`,
    structure: `${label} anlatısının türe özgü aşamalarını gösteren yapı diyagramı`,
    anatomy: `${label} eserinin birlikte çalışması gereken temel parçalarını gösteren eser anatomisi`,
    pageSetup: `${label} yazımı için sahne kartları, araştırma notları ve süreklilik kayıtlarını gösteren pratik çalışma düzeni`,
    project: `${project} adlı örnek projenin karakter, çatışma ve yapı notlarını gösteren çalışma panosu`,
    finalCta: `${label} taslağını tamamlayıp İlkOku Yazar Alanı'nda yazmaya geçmeye hazırlanan çalışma ortamı`,
  };
}

